import numpy as np

def hexagon_packing_12():
    # Define the 12 centers in a "7 + 5" topology
    # Center
    centers = [[0.0, 0.0]]
    
    # Ring 1 (6 hexes)
    # Angles 30, 90, 150, 210, 270, 330
    # Distance sqrt(3)
    d1 = np.sqrt(3)
    for i in range(6):
        angle = np.deg2rad(30 + 60*i)
        centers.append([d1 * np.cos(angle), d1 * np.sin(angle)])
        
    # Ring 2 (pick 5)
    # We need to identify the Ring 2 positions.
    # The lattice is generated by vectors v1 = (sqrt(3)/2, 1.5) and v2 = (sqrt(3), 0)?
    # Let's just generate a grid of hexes and pick the ones at distance ~ 2*sqrt(3)
    # Actually, simpler: The 12 Ring 2 hexes are at distance 2*sqrt(3) from center?
    # No, the "hexagonal distance" is 2 steps.
    # I will hardcode the 12 Ring 2 coordinates or generate them.
    # Generation:
    # Axial coordinates for Ring 2 are those with max(|q|, |r|, |q+r|) = 2?
    # No, that's for pointy top.
    # For flat top, let's just use the Cartesian neighbors of Ring 1.
    
    ring2 = []
    # For each ring 1 hex, find its outward neighbors
    # This is getting complicated to implement robustly in a short time.
    # Alternative: Use a known optimal packing for 12.
    # A 3x4 parallelogram is simpler to code.
    # Let's use the 3x4 parallelogram.
    
    centers = []
    # Row 0
    for i in range(4):
        centers.append([2*i, 0])
    # Row 1
    for i in range(4):
        centers.append([2*i + 1, np.sqrt(3)/2])
    # Row 2
    for i in range(4):
        centers.append([2*i, np.sqrt(3)])
        
    centers = np.array(centers)
    
    # Optimize rotation
    best_s = float('inf')
    best_theta = 0
    
    # Normals of the outer hexagon (flat-top)
    # Edges are perpendicular to 30, 90, ...
    normals = []
    for i in range(6):
        angle = np.deg2rad(30 + 60*i)
        normals.append([np.cos(angle), np.sin(angle)])
    normals = np.array(normals)
    
    # Search theta
    for theta_deg in np.linspace(0, 60, 601):
        theta = np.deg2rad(theta_deg)
        c = np.cos(theta)
        s = np.sin(theta)
        rot = np.array([[c, -s], [s, c]])
        
        rotated_centers = centers @ rot.T
        
        # Project onto normals
        # projections = rotated_centers @ normals.T
        # max_proj = np.max(np.abs(projections))
        # s_required = 2 * max_proj / np.sqrt(3)
        
        projections = rotated_centers @ normals.T
        max_proj = np.max(np.abs(projections))
        s_required = 2 * max_proj / np.sqrt(3)
        
        if s_required < best_s:
            best_s = s_required
            best_theta = theta

    # Apply best rotation
    c = np.cos(best_theta)
    s = np.sin(best_theta)
    rot = np.array([[c, -s], [s, c]])
    final_centers = centers @ rot.T
    
    inner_hex_data = np.column_stack((final_centers[:, 0], final_centers[:, 1], np.zeros(12)))
    outer_hex_data = np.array([0.0, 0.0, 0.0])
    
    return inner_hex_data, outer_hex_data, best_s

hexagon_packing_12()
